import{_ as r,o,c as a,ag as e,j as s}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"dotNET","description":"","frontmatter":{"title":"dotNET","aliases":[".NET","dotnet",".NET 10",".NET Core",".NET生态",".NET总览"],"tags":["dotNET","总览"],"status":"ai-draft","sources":["https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core","https://learn.microsoft.com/en-us/dotnet/framework/install/how-to-determine-which-versions-are-installed","https://dotnet.microsoft.com/platform/support/policy/dotnet-framework","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"30-.NET生态/dotNET.md","filePath":"30-.NET生态/dotNET.md"}'),i={name:"30-.NET生态/dotNET.md"},n={style:{"overflow-x":"auto"}},l={viewBox:"0 0 760 330",style:{"min-width":"720px",width:"100%","font-family":"sans-serif","font-size":"14px"},xmlns:"http://www.w3.org/2000/svg"};function d(h,t,p,c,E,g){return o(),a("div",null,[t[1]||(t[1]=e('<blockquote><p>本篇是 <code>30-.NET生态</code> 的总览页，也是 23 篇词条的入门路径。读完你应该能：说清 .NET 由哪几块组成、和 C# 是什么关系、手上的项目该用哪种&quot;应用类型&quot;；并知道下面 22 篇按什么顺序读。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>.NET</strong> 是微软的开源开发平台：一个<strong>运行时</strong>（负责执行程序）+ 一套<strong>基础类库</strong>（现成的工具箱）+ 一个 <strong>SDK</strong>（编译、打包、发布用的命令行工具），用它可以写网站、桌面程序、后台服务、命令行工具，用的语言主要是 <a href="/Encyclopedia/20-编程语言/CSharp/CSharp">CSharp</a>。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>会一点 <a href="/Encyclopedia/20-编程语言/CSharp/CSharp">CSharp</a>（变量、类、方法）。没学过也能看懂本篇，但动手部分需要。</li><li>会在 <a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a> 里敲命令、知道 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>。</li><li>知道 <a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a> 请求和响应长什么样（读 Web 相关几篇时用得上）。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>假设你要给工厂写一个&quot;工单查询&quot;程序。如果只有一门语言（C#）的语法，你还缺很多东西：</p><ul><li>程序怎么<strong>运行</strong>？谁把你写的代码变成 CPU 能执行的指令？（运行时）</li><li>怎么读文件、发网络请求、处理日期、操作集合？总不能每样都从零写。（基础类库）</li><li>怎么编译、还原第三方库、打包发布？（SDK 与 <a href="/Encyclopedia/30-.NET生态/NuGet">NuGet</a>）</li><li>怎么快速搭一个能被别人调用的网络接口，或一个带窗口的桌面程序？（各种应用框架）</li></ul><p>.NET 就是把这些&quot;周边&quot;全包办的一整套东西。语言只管&quot;怎么写&quot;，平台管&quot;怎么跑、有什么可用&quot;。</p><p><strong>类比</strong>：C# 是你写菜谱用的语言；.NET 是整个厨房——灶台（运行时）、锅碗瓢盆（基础类库）、采购渠道（NuGet）、还有不同类型的档口（Web、桌面、后台服务）。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="net-的四层" tabindex="-1">.NET 的四层 <a class="header-anchor" href="#net-的四层" aria-label="Permalink to &quot;.NET 的四层&quot;">​</a></h3>',12)),s("div",n,[(o(),a("svg",l,[...t[0]||(t[0]=[e('<rect x="20" y="10" width="720" height="62" rx="8" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="40" y="35" font-weight="bold" fill="currentColor">应用类型（你选一种或几种）</text><text x="40" y="58" fill="currentColor">ASP.NET Core（网站/API） · WinForms/WPF（桌面） · Worker Service（后台） · 控制台 · 测试</text><rect x="20" y="82" width="720" height="62" rx="8" fill="currentColor" fill-opacity="0.14" stroke="currentColor"></rect><text x="40" y="107" font-weight="bold" fill="currentColor">第三方库（NuGet 包）</text><text x="40" y="130" fill="currentColor">SqlSugar · Dapper · NModbus · Newtonsoft.Json · xUnit ……</text><rect x="20" y="154" width="720" height="62" rx="8" fill="currentColor" fill-opacity="0.20" stroke="currentColor"></rect><text x="40" y="179" font-weight="bold" fill="currentColor">基础类库 BCL（随运行时安装）</text><text x="40" y="202" fill="currentColor">字符串、集合、文件 IO、网络、线程、JSON、日期……（System.* 命名空间）</text><rect x="20" y="226" width="720" height="62" rx="8" fill="currentColor" fill-opacity="0.28" stroke="currentColor"></rect><text x="40" y="251" font-weight="bold" fill="currentColor">运行时 CLR（公共语言运行时）</text><text x="40" y="274" fill="currentColor">JIT 编译器 · 垃圾回收器 GC · 类型系统 · 程序集加载</text><text x="40" y="313" fill="currentColor">最底下是操作系统：Windows / Linux / macOS。SDK 是“开发时”的工具箱，不在这张运行图里。</text>',13)])]))]),t[2]||(t[2]=e(`<ol><li><strong>运行时（CLR）</strong>：把编译产物（IL，一种中间语言）再编译成本机机器码并执行，同时负责内存回收。详见 <a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>。</li><li><strong>基础类库（BCL，Base Class Library）</strong>：<code>System.*</code> 开头的一大批现成类。<code>List&lt;T&gt;</code>、<code>File</code>、<code>HttpClient</code>、<code>Console</code> 都在这里。</li><li><strong>第三方库</strong>：别人写好、发布在 <a href="/Encyclopedia/30-.NET生态/NuGet">NuGet</a> 上的包，一条命令引进来。</li><li><strong>应用类型</strong>：决定你的程序&quot;长什么样&quot;。每种类型对应一个 <strong>SDK 变体</strong>，写在 <code>.csproj</code> 第一行。</li></ol><h3 id="net-与-c-的关系" tabindex="-1">.NET 与 C# 的关系 <a class="header-anchor" href="#net-与-c-的关系" aria-label="Permalink to &quot;.NET 与 C# 的关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>C#</th><th>.NET</th></tr></thead><tbody><tr><td>是什么</td><td>一门编程语言</td><td>一个平台（运行时 + 类库 + 工具）</td></tr><tr><td>管什么</td><td>语法：怎么写 <code>if</code>、<code>class</code>、<code>async</code></td><td>程序怎么编译、运行、有什么库可用</td></tr><tr><td>能换吗</td><td>同一个平台还支持 F#、VB</td><td>C# 也可以跑在别的平台（如 Unity 的 Mono），但工厂系统基本都用 .NET</td></tr></tbody></table><p>两者经常被混着叫。简单记：<strong>写的是 C#，跑在 .NET 上</strong>。</p><h3 id="net-framework-和现在的-net-不是一个东西" tabindex="-1">.NET Framework 和现在的 .NET 不是一个东西 <a class="header-anchor" href="#net-framework-和现在的-net-不是一个东西" aria-label="Permalink to &quot;.NET Framework 和现在的 .NET 不是一个东西&quot;">​</a></h3><p>这是新手最容易晕的地方，历史是这样的：</p><table tabindex="0"><thead><tr><th>名称</th><th>时期</th><th>特点</th></tr></thead><tbody><tr><td><strong>.NET Framework</strong> 1.0–4.8</td><td>2002 起</td><td><strong>只能在 Windows</strong> 上跑，随 Windows 自带；很多工厂老系统（WinForms 的 MES 客户端、ASP.NET MVC 5、WCF）都是它</td></tr><tr><td><strong>.NET Core</strong> 1.0–3.1</td><td>2016 起</td><td>重写的跨平台版本，开源</td></tr><tr><td><strong>.NET</strong> 5、6、7、8、9、10</td><td>2020 起</td><td>.NET Core 改名并统一后的名字，<strong>去掉了 &quot;Core&quot;</strong>。现在说&quot;.NET&quot;一般指这个</td></tr></tbody></table><blockquote><p>注意：<strong>ASP.NET Core</strong> 这个名字里的 &quot;Core&quot; 保留了，它是 .NET 上的 Web 框架（对应老的 ASP.NET）。别和 &quot;.NET Core&quot; 混。</p></blockquote><p>本机实测：你的电脑上 PowerShell 5.1 跑在 .NET Framework 4.8 上，而 <code>dotnet</code> 命令跑的是新 .NET。两套<strong>同时装在一台机器上互不干扰</strong>。</p><h3 id="版本与支持期-2026-10-21-查证" tabindex="-1">版本与支持期（2026-10-21 查证） <a class="header-anchor" href="#版本与支持期-2026-10-21-查证" aria-label="Permalink to &quot;版本与支持期（2026-10-21 查证）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>类型</th><th>发布</th><th>结束支持</th></tr></thead><tbody><tr><td>.NET 8</td><td>LTS（长期支持，3 年）</td><td>2023-11-14</td><td><strong>2026-11-10</strong></td></tr><tr><td>.NET 9</td><td>STS（标准支持，2 年）</td><td>2024-11-12</td><td><strong>2026-11-10</strong></td></tr><tr><td>.NET 10</td><td>LTS</td><td>2025-11-11</td><td>2028-11-14</td></tr></tbody></table><p>规则：偶数版本是 LTS，奇数是 STS。<strong>新项目选 LTS（当前就是 .NET 10）</strong>。.NET 8 和 .NET 9 都将在 2026-11-10 结束支持，仍在用的项目要尽快规划升级。.NET Framework 4.8/4.8.1 则作为 Windows 的组件，随所在 Windows 版本一起受支持。数据来自 <a href="https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core" target="_blank" rel="noreferrer">微软支持策略页</a> 和 <a href="https://dotnet.microsoft.com/platform/support/policy/dotnet-framework" target="_blank" rel="noreferrer">.NET Framework 支持策略</a>。</p><h3 id="各种应用类型一览" tabindex="-1">各种应用类型一览 <a class="header-anchor" href="#各种应用类型一览" aria-label="Permalink to &quot;各种应用类型一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你想做的</th><th>用什么</th><th>本库对应词条</th></tr></thead><tbody><tr><td>网站、给别人调用的 HTTP 接口</td><td>ASP.NET Core</td><td><a href="/Encyclopedia/30-.NET生态/ASP.NET-Core">ASP.NET-Core</a>、<a href="/Encyclopedia/30-.NET生态/WebAPI开发">WebAPI开发</a></td></tr><tr><td>带窗口的 Windows 桌面程序</td><td>WinForms（简单直接）/ WPF（界面更灵活）</td><td><a href="/Encyclopedia/30-.NET生态/WinForms">WinForms</a>、<a href="/Encyclopedia/30-.NET生态/WPF">WPF</a></td></tr><tr><td>后台常驻任务、Windows 服务</td><td>Worker Service</td><td><a href="/Encyclopedia/30-.NET生态/后台服务与Windows服务">后台服务与Windows服务</a></td></tr><tr><td>命令行小工具、一次性脚本</td><td>控制台应用</td><td><a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a> 里的实验</td></tr><tr><td>自动化测试</td><td>xUnit 等</td><td><a href="/Encyclopedia/30-.NET生态/xUnit单元测试">xUnit单元测试</a></td></tr><tr><td>手机/跨平台界面</td><td>MAUI（本库不展开）</td><td>—</td></tr></tbody></table><p>工厂里最常见的组合：<strong>WinForms/WPF 客户端 + ASP.NET Core Web API + SQL Server</strong>（数据层用 <a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a>）。</p><h2 id="逐步例子-一分钟确认你的-net-环境" tabindex="-1">逐步例子：一分钟确认你的 .NET 环境 <a class="header-anchor" href="#逐步例子-一分钟确认你的-net-环境" aria-label="Permalink to &quot;逐步例子：一分钟确认你的 .NET 环境&quot;">​</a></h2><p>打开 PowerShell，依次执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdks</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtimes</span></span></code></pre></div><p>本机实际输出（节选）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10.0.401</span></span>
<span class="line"><span>10.0.401 [C:\\Program Files\\dotnet\\sdk]</span></span>
<span class="line"><span>Microsoft.NETCore.App 8.0.31 [C:\\Program Files\\dotnet\\shared\\Microsoft.NETCore.App]</span></span>
<span class="line"><span>Microsoft.NETCore.App 9.0.20 [C:\\Program Files\\dotnet\\shared\\Microsoft.NETCore.App]</span></span>
<span class="line"><span>Microsoft.NETCore.App 10.0.12 [C:\\Program Files\\dotnet\\shared\\Microsoft.NETCore.App]</span></span>
<span class="line"><span>Microsoft.WindowsDesktop.App 10.0.12 [C:\\Program Files\\dotnet\\shared\\Microsoft.WindowsDesktop.App]</span></span></code></pre></div><p>读法：本机装了 <strong>一个 SDK（10.0.401）</strong>，和多个版本的<strong>运行时</strong>。SDK 能编译所有旧版本的项目，所以只装最新 SDK 即可。<code>Microsoft.NETCore.App</code> 是基础运行时，<code>Microsoft.AspNetCore.App</code> 是 Web 运行时，<code>Microsoft.WindowsDesktop.App</code> 是 WinForms/WPF 所需。</p><h2 id="动手实验-从零做出一个会运行的网站" tabindex="-1">动手实验：从零做出一个会运行的网站 <a class="header-anchor" href="#动手实验-从零做出一个会运行的网站" aria-label="Permalink to &quot;动手实验：从零做出一个会运行的网站&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mkdir hello</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">net ; cd hello</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">net</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet new web </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n Hello</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd Hello</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">urls http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5101</span></span></code></pre></div><p>看到 <code>Now listening on: http://localhost:5101</code> 后，<strong>另开一个</strong> PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5101</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span></span></code></pre></div><p>预期输出：<code>Hello World!</code>。回到第一个窗口按 <code>Ctrl+C</code> 停止。</p><p>三条命令、一个 <code>Program.cs</code>（4 行有效代码），一个网站就跑起来了。后面几篇会把它一点点长大。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>新旧混淆</strong>：网上教程写 <code>.NET Core 3.1</code> 或 <code>.NET Framework 4.7</code>，写法和 .NET 10 有差异。先看教程的版本；本库统一以 .NET 10 为准。</li><li><strong>只装运行时没装 SDK</strong>：<code>dotnet run</code>、<code>dotnet build</code> 报&quot;找不到 SDK&quot;。开发机装 SDK，服务器只需运行时。</li><li><strong>本机有代理时 <code>localhost</code> 请求返回 502/503</strong>：命令行工具（<code>curl.exe</code>）会读环境变量 <code>HTTP_PROXY</code> 把本地请求也发给代理。给 <code>curl.exe</code> 加 <code>--noproxy &quot;*&quot;</code>，或设置 <code>NO_PROXY=localhost</code>。</li><li><strong>端口被占用</strong>：<code>Failed to bind to address ... address already in use</code>，换一个端口（<code>--urls</code>）。</li></ul><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><p><strong>业务视角</strong>：工厂的信息化系统寿命很长，十年前的 .NET Framework 程序现在还在产线上跑。&quot;升级&quot;不是技术炫耀，而是为了：安全补丁（过期版本不再修漏洞）、能在服务器上并存多个版本、性能（微软每个版本都有优化，新版通常更快）、能用上新库（很多新库不再支持 .NET Framework）。</p><p><strong>技术视角</strong>：升级前先确认依赖库是否有 <code>net8.0</code>/<code>net10.0</code> 版本；WCF、Web Forms 等技术在新 .NET 中没有直接对应物，需要重写或用 CoreWCF 等替代方案（迁移细节本库未展开，以微软迁移指南为准）。</p><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>运行 <code>dotnet --list-runtimes</code>，找出你机器上有哪几个大版本的 .NET 运行时。 <strong>答</strong>：看第一列的版本号前缀（如 6、8、9、10）。</li><li>某同事说&quot;我的 MES 客户端是 .NET Core 3.1&quot;。它现在还受支持吗？ <strong>答</strong>：不受支持。.NET Core 3.1 早已结束支持；应升级到当前 LTS（.NET 10）。</li><li>为什么说 SDK 和运行时不是一回事？ <strong>答</strong>：SDK 在开发时用来编译、打包；运行时在程序运行时用。服务器上只装运行时就能跑已发布的程序。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>.NET = 运行时 + 基础类库 + SDK；C# 是语言，.NET 是平台。</li><li>.NET Framework（只限 Windows，老）和 .NET（跨平台，新，现在是 10）是两套东西，可并存。</li><li>新项目选 LTS 版本；8/9 在 2026-11-10 结束支持。</li><li>应用类型决定你读哪几篇：Web、桌面、后台服务。</li></ul><h2 id="入门路径-23-篇" tabindex="-1">入门路径（23 篇） <a class="header-anchor" href="#入门路径-23-篇" aria-label="Permalink to &quot;入门路径（23 篇）&quot;">​</a></h2><p>按下面顺序读最顺；标&quot;选读&quot;的可以跳过，用到再回头。</p><p><strong>第一站：平台基础</strong></p><ol><li><a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a>（本篇）</li><li><a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>：CLR、JIT、程序集、<code>dotnet</code> 命令、<code>global.json</code></li><li><a href="/Encyclopedia/30-.NET生态/NuGet">NuGet</a>：引用第三方库</li></ol><p><strong>第二站：Web 后端主线（工厂接口开发的核心）</strong> 4. <a href="/Encyclopedia/30-.NET生态/ASP.NET-Core">ASP.NET-Core</a>：总览与最小 API 5. <a href="/Encyclopedia/30-.NET生态/WebAPI开发">WebAPI开发</a>：控制器、路由、模型绑定，做一个&quot;工单查询&quot;API 6. <a href="/Encyclopedia/30-.NET生态/中间件与请求管道">中间件与请求管道</a>：请求怎么一层层经过你的程序 7. <a href="/Encyclopedia/30-.NET生态/依赖注入">依赖注入</a>：Transient / Scoped / Singleton 8. <a href="/Encyclopedia/30-.NET生态/配置与日志">配置与日志</a>：appsettings、环境变量、<code>ILogger</code> 9. <a href="/Encyclopedia/30-.NET生态/System.Text.Json">System.Text.Json</a>：JSON 序列化 10. <a href="/Encyclopedia/30-.NET生态/HttpClient">HttpClient</a>：调用别人的接口 11. <a href="/Encyclopedia/30-.NET生态/Swagger与OpenAPI">Swagger与OpenAPI</a>：自动生成接口文档 12. <a href="/Encyclopedia/30-.NET生态/身份认证与JWT">身份认证与JWT</a>：登录与令牌 13. <a href="/Encyclopedia/30-.NET生态/部署到IIS">部署到IIS</a>：把网站放到服务器上</p><p><strong>第三站：数据访问（三选一入门，建议先学 SqlSugar）</strong> 14. <a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a>：本库默认用它 15. <a href="/Encyclopedia/30-.NET生态/EF-Core">EF-Core</a>：微软官方 ORM（选读） 16. <a href="/Encyclopedia/30-.NET生态/Dapper">Dapper</a>：轻量、手写 SQL（选读）</p><p><strong>第四站：桌面程序</strong> 17. <a href="/Encyclopedia/30-.NET生态/WinForms">WinForms</a>：简单直接，适合快速做工具 18. <a href="/Encyclopedia/30-.NET生态/WPF">WPF</a>：界面更灵活（选读）</p><p><strong>第五站：后台与测试</strong> 19. <a href="/Encyclopedia/30-.NET生态/后台服务与Windows服务">后台服务与Windows服务</a> 20. <a href="/Encyclopedia/30-.NET生态/xUnit单元测试">xUnit单元测试</a></p><p><strong>第六站：和设备打交道（工厂特色）</strong> 21. <a href="/Encyclopedia/30-.NET生态/CSharp-TCP通信">CSharp-TCP通信</a> 22. <a href="/Encyclopedia/30-.NET生态/CSharp串口通信">CSharp串口通信</a> 23. <a href="/Encyclopedia/30-.NET生态/NModbus">NModbus</a>：用库读 PLC/仪表的 Modbus 数据（原理见 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>）</p><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/20-编程语言/CSharp/CSharp">CSharp</a> · <a href="/Encyclopedia/10-计算机基础/计算机网络/HTTP">HTTP</a> · <a href="/Encyclopedia/50-工具与工程/REST-API设计">REST-API设计</a> · <a href="/Encyclopedia/50-工具与工程/软件架构分层">软件架构分层</a> · <a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server">SQL-Server</a> · <a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>微软 .NET 文档入口：<a href="https://learn.microsoft.com/dotnet/" target="_blank" rel="noreferrer">https://learn.microsoft.com/dotnet/</a></li><li>.NET 支持策略：<a href="https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core" target="_blank" rel="noreferrer">https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core</a></li></ul>`,49))])}const k=r(i,[["render",d]]);export{u as __pageData,k as default};
